def is_valid_schedule(shifts):
    # Check rule 1: start < end for every shift
    for shift in shifts:
        if shift[0] >= shift[1]:
            return False

    # Check rule 2: both start and end are between 0 and 1440
    for shift in shifts:
        if not (0 <= shift[0] <= 1440) or not (0 <= shift[1] <= 1440):
            return False

    # Check rule 3: shift length is between 30 and 240 minutes
    for shift in shifts:
        if not (30 <= shift[1] - shift[0] <= 240):
            return False

    # Check rule 4: no overlapping shifts
    sorted_shifts = sorted(shifts)
    for i in range(1, len(sorted_shifts)):
        if sorted_shifts[i][0] < sorted_shifts[i-1][1]:
            return False

    # Check rule 5: at least 15 minutes break between shifts
    for i in range(1, len(sorted_shifts)):
        if sorted_shifts[i][0] < sorted_shifts[i-1][1] - 15:
            return False

    # Check rule 6: total time is at most 600 minutes
    total_time = sum(end - start for start, end in shifts)
    if total_time > 600:
        return False

    # Rule 7: empty schedule is valid
    if not shifts:
        return True

    return True
